import json,hashlib,csv,math,sys
from pathlib import Path
import numpy as np
import torch
from sklearn.metrics import roc_auc_score,average_precision_score
r=Path('.'); E=r/'docs/thesis_evidence'
out={'official':{},'masks':{},'loss':{},'gradients':{},'pilot':{},'hashes':{}}
def rows(p): return list(csv.DictReader(p.open(encoding='utf-8-sig')))
d=torch.load('artifacts/data/shapeggen.pt',map_location='cpu',weights_only=False)
print('DATA_TYPE',type(d).__name__, list(d.keys()) if isinstance(d,dict) else str(d)[:700])
for bb in ['gcn','graphsage']:
 for method in ['gnnexplainer','pgexplainer','random']:
  p=r/f'results/metrics/shapeggen/{bb}/{method}'/('random_node_level_metrics.csv' if method=='random' else 'per_node_metrics.csv')
  rr=rows(p);out['official'][bb+'/'+method]={'n':len(rr),'auroc':float(np.mean([float(x['edge_auroc']) for x in rr])),'ap':float(np.mean([float(x['edge_ap']) for x in rr])),'ids':[int(x['node_id']) for x in rr]}
p=E/'shapeggen_v1_pg_gcn_loss_probe/09_LOSS_PROBE_RESULTS.json';loss=json.loads(p.read_text())
for bb,b in loss['backbones'].items():
 out['loss'][bb]={}
 for cohort in ['train','test']:
  cf=b['counterfactuals'][cohort]['per_target'];o={}
  for state,rr in cf.items():
   o[state]={'n':len(rr),**{k:float(np.mean([x[k] for x in rr])) for k in ['prediction_ce','size','entropy','total']},'preserved':sum(1-x['flip'] for x in rr)}
  for state in ['LEARNED','ZERO']:
   one={x['node_id']:x for x in cf['ONE']};o[state]['lower_total_than_ONE']=sum(x['total']<one[x['node_id']]['total'] for x in cf[state])
  out['loss'][bb][cohort]=o
 for mode,key in [('deterministic','deterministic_gradient_per_target'),('Concrete','stochastic_per_sample')]:
  rr=b[key];out['gradients'][bb+'/'+mode]={'n':len(rr),'ids':sorted(set(x['node_id'] for x in rr)),'components':{}}
  for comp in ['prediction_ce','size','entropy','total']:
   out['gradients'][bb+'/'+mode]['components'][comp]={space:float(np.mean([x['gradients']['components'][comp][space]['l2'] for x in rr])) for space in ['soft_hard','raw_hard','mlp_parameters']}
pilot=json.loads((E/'shapeggen_v1_pg_size_pilot/16_STEP02B_RESULTS.json').read_text())
for k,b in pilot['runs'].items():
 rr=b['rows'];out['pilot'][k]={'n':len(rr),**{m:float(np.mean([float(x[m]) for x in rr])) for m in ['edge_auroc','edge_ap','near_zero_fraction','score_mean','topk_gt_precision','topk_gt_recall','fid_plus','fid_minus']},'ids':[int(x['node_id']) for x in rr]}
out['pilot_gates']=pilot['acceptance']
print('AUDIT_COMPACT='+json.dumps(out))
